select count(*) from sales where qty >=3 ;
select * from products

/* Q15) Consider 10 zomato points = Rs 2
		For	Product: P1 - P6 = 5 points / item
					 P7 - P10 = 10 points / item
					 P11 - P25 = 5 points / item
	Then, Calculate how many zomato points have been collected so far by individual user and 
	for which product maximum zomato points have been rewarded to customers so far. 
*/

create table  zomato_points as 
select s.user_id,p.product_name,sum(s.qty),
case 
    when p.product_name in ('P7', 'P8', 'P9', 'P10') then sum(s.qty) * 10
	else sum(s.qty) *5
end as zomato_points
from sales as s join products as p on s.products_id = p.products_id
group by 1,2
order by 2 desc;


select * from zomato_points;
-- Zomato points have been collected so far by individual user
select user_id ,sum(zomato_points) as total_points from zomato_points group by user_id order by 2 desc;

--  which  zomato product points rewarded to customers maximum

select product_name,sum(zomato_points) as total_points,round(sum(zomato_points)/5,0) as rewards_amount 
from zomato_points group by 1 order by 2 desc,3 desc;

select * from sales


/* Q16) Find top selling month of each year ? */
select * from (
select s.year,
       s.month_name ,
	   sum(s.qty * p.price_i) as total_sell,
	   row_number() over (
	                partition by s.year 
					order by sum(s.qty * p.price_i) desc 
					) as rnk 
from sales as s 
join products as p 
     on s.products_id=p.products_id 
group by 1,2 ) t 
where rnk=1;

/* Q17) see the sell difference of each month with previous month ? */

select s.year,
       s.month_name,
	   s.month,
	   sum(s.qty * p.price_i) as total_sell,
	   lag(sum(s.qty * p.price_i)) over (
	                partition by s.year 
					order by s.month asc 
					) as previous_month_sell ,
		sum(s.qty * p.price_i) - lag(sum(s.qty * p.price_i)) over (partition by s.year order by s.month asc ) as Difference 
from sales as s 
join products as p 
     on s.products_id=p.products_id 
group by 1,2,3;











